from math import comb, factorial
from fractions import Fraction
C={(0,0):1}
active_bounds={}
for n in range(1,4):
    for a in range(n+1):
        alpha=(a,n-a)
        choices=[]
        for j in range(2):
            if not alpha[j]:
                choices.append(0)
                continue
            total=0
            for l in range(1,alpha[j]+1):
                beta=list(alpha); beta[j]-=l
                total+=comb(alpha[j],l)*C[tuple(beta)]
            choices.append(total)
        C[alpha]=max(choices)
        active_bounds[alpha]=choices
assert C=={(0,0):1,(0,1):1,(1,0):1,(0,2):3,(1,1):1,(2,0):3,(0,3):13,(1,2):3,(2,1):3,(3,0):13}
value=[Fraction(C[a,3-a],factorial(a)*factorial(3-a)) for a in [3,2,1,0]]
plus=[Fraction(C[a+1,2-a],factorial(a)*factorial(2-a)) for a in [2,1,0]]
minus=[Fraction(C[a,3-a],factorial(a)*factorial(2-a)) for a in [2,1,0]]
assert value==[Fraction(13,6),Fraction(3,2),Fraction(3,2),Fraction(13,6)]
assert plus==[Fraction(13,2),Fraction(3),Fraction(3,2)]
assert minus==[Fraction(3,2),Fraction(3),Fraction(13,2)]
results={'C':{str(k):v for k,v in C.items()},'active_direction_forcing_bounds':{str(k):v for k,v in active_bounds.items()},'value_coefficients_p_descending':list(map(str,value)),'plus_gradient_coefficients_p_descending':list(map(str,plus)),'minus_gradient_coefficients_p_descending':list(map(str,minus)),'arithmetic':'exact integers and Fraction','all_assertions_pass':True}
